"use strict";(self.webpackChunklearning=self.webpackChunklearning||[]).push([[6153],{6153:(n,h,t)=>{t.r(h),t.d(h,{math:()=>i});const i=[{semester:1,grade:8,questions:[{id:41,extra:"",question:"<p>Hai xe kh\u1edfi h\xe0nh c\xf9ng m\u1ed9t l\xfac t\u1eeb hai \u0111\u1ecba \u0111i\u1ec3m A v\xe0 B c\xe1ch nhau 140 km v\xe0 sau 2 gi\u1edd th\xec g\u1eb7p nhau. T\xednh v\u1eadn t\u1ed1c c\u1ee7a m\u1ed7i xe bi\u1ebft xe \u0111i t\u1eeb A c\xf3 v\u1eadn t\u1ed1c l\u1edbn h\u01a1n xe \u0111i t\u1eeb B l\xe0 10 km/h ?</p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:"<p>G\u1ecdi v\u1eadn t\u1ed1c xe \u0111i t\u1eeb A l\xe0 x ( km/h) (x > 10)</br>\n      V\u1eadn t\u1ed1c xe \u0111i t\u1eeb B : x - 10 (km/h)</br>\nQu\xe3ng \u0111\u01b0\u1eddng xe \u0111i t\u1eeb A \u0111i \u0111\u01b0\u1ee3c trog 2h: 2x (km)</br>\nQu\xe3ng \u0111\u01b0\u1eddng xe \u0111i t\u1eeb B \u0111i \u0111\u01b0\u1ee3c trog 2h: 2( x - 10 ) (km)</br>\nTheo \u0111\u1ec1 b\xe0i ta c\xf3 ph\u01b0\u01a1ng tr\xecnh:</br>\n2x + 2 (x - 10) =140</br>\n<=> 2x + 2x - 20 = 140</br>\n<=> 4x = 160</br>\n<=> x = 40 ( TM\u0110K)</br>\nV\u1eady v\u1eadn t\u1ed1c xe \u0111i t\u1eeb A l\xe0 40 km/h</br>\n       V\u1eadn t\u1ed1c xe \u0111i t\u1eeb B= 40 - 10 = 30 km/h.</p>"},{id:41,extra:"",question:"<p>M\u1ed9t ng\u01b0\u1eddi \u0111i xe m\xe1y t\u1eeb A \u0111\u1ebfn B v\u1edbi v\u1eadn t\u1ed1c  40 km/h . \u0110\u1ebfn B ng\u01b0\u1eddi \u0111\xf3 l\xe0m vi\u1ec7c trong 3 gi\u1edd r\u1ed3i quay v\u1ec1 A v\u1edbi v\u1eadn t\u1ed1c 30km/h . Bi\u1ebft th\u1eddi gian t\u1ed5ng c\u1ed9ng h\u1ebft 6 gi\u1edd 30 ph\xfat . T\xednh qu\xe3ng \u0111\u01b0\u1eddng AB ?</p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:"<p>G\u1ecdi x l\xe0 qu\xe3ng \u0111\u01b0\u1eddng t\u1eeb A \u0111\u1ebfn B</br>\n              T\u1ed5ng th\u1eddi gian \u0111i v\xe0 v\u1ec1 l\xe0 6.5 - 3=3.5</br>\n              V\u1eacy th\u1eddi gian ng\u01b0\u1eddi \u0111\xf3 \u0111i t\u1eeb A \u0111\u1ebfn B v\xe0 t\u1eeb B v\u1ec1 A l\xe0 : x/40 + x/30=3.5</br>\n                <=> (3x + 4x)/120 = 3.5</br>\n                <=> 7x = 3.5.120</br>\n                <=> x = 60 (km)</br>\n              </p>"},{id:41,extra:"",question:"<p>M\u1ed9t \xf4t\xf4 d\u1ef1 \u0111\u1ecbnh \u0111i qu\xe3ng \u0111\u01b0\u1eddng AB d\xe0i 60km trong m\u1ed9t th\u1eddi gian nh\u1ea5t \u0111\u1ecbnh. \xd4t\xf4 \u0111i n\u1eefa \u0111\u1ecdan \u0111\u01b0\u1eddng \u0111\u1ea7u v\u1edbi v\u1eadn t\u1ed1c l\u1edbn h\u01a1n d\u1ef1 \u0111\u1ecbnh l\xe0 10km/h, v\xe0 \u0111i n\u1eefa \u0111o\u1ea1n \u0111\u01b0\u1eddng sau v\u1edbi v\u1eadn t\u1ed1c b\xe9 h\u01a1n d\u1ef1 \u0111\u1ecbnh l\xe0 6km/h. Bi\u1ebft \xf4t\xf4 \u0111\u1ebfn B \u0111\xfang th\u1eddi gian \u0111\xe3 \u0111\u1ecbnh. T\xednh th\u1eddi gian \xf4t\xf4 d\u1ef1 \u0111\u1ecbnh \u0111i h\u1ebft qu\xe3ng \u0111\u01b0\u1eddng AB ?</p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:"<p>G\u1ecdi x v\xe0 v\u1eadn t\u1ed1c d\u1ef1 t\xednh c\u1ee7a o6to6 \u0111i h\u1ebft qu\xe3ng \u0111\u01b0\u1eddng AB</br>\n              V\u1eacy th\u1eddi gian \u0111i h\u1ebft qu\xe3ng \u0111\u01b0\u1eddng d\u1ef1 t\xednh l\xe0: 60/x (1)</br>\n              N\u1eefa qu\xe3ng \u0111\u01b0\u1eddng oto \u0111i v\u1edbi v\u1eadn t\u1ed1c x +10, th\xec m\u1ea5t 30/(x+10) gi\u1edd (2)</br>\n              N\u1eefa qu\xe3ng d\u01b0\u1eddng sau oto \u0111i v\u1edbi v\u1eadn t\u1ed1c x-6, th\xec m\u1ea5t 30/(x-6) gi\u1edd (3)</br>\n              V\xec th\u1eddi gia \u0111i th\u1ef1c t\u1ebf v\xe0 th\u1eddi gian d\u1ef1 \u0111\u1ecbnh l\xe0 nh\u01b0 nhau n\xean:</br>\n              60/x = 30/(x+10) + 30/(x-6)\n              Gi\u1ea3i ph\u01b0\u01a1ng th\xecnh ta \u0111\u01b0\u1ee3c x=30 km/h</br>\n              V\u1eacy th\u1eddi gian d\u1ef1 \u0111\u1ecbnh l\xe0: 60/30=2 h</p>"},{id:41,extra:"",question:"<p>M\u1ed9t x\xed nghi\u1ec7p d\u1ef1 \u0111\u1ecbnh s\u1ea3n xu\u1ea5t 1500 s\u1ea3n ph\u1ea9m trong 30 ng\xe0y. Nh\u01b0ng nh\u1edd t\u1ed5 ch\u1ee9c lao \u0111\u1ed9ng h\u1ee3p l\xed n\xean \u0111\xe3 s\u1ea3n xu\u1ea5t m\u1ed7i ng\xe0y v\u01b0\u1ee3t 15 s\u1ea3n ph\u1ea9m. Do \u0111\xf3 x\xed nghi\u1ec7p \u0111\xe3 s\u1ea3n xu\u1ea5t kh\xf4ng v\u01b0\u1ee3t m\u1ee9c d\u1ef1 \u0111\u1ecbnh 255 s\u1ea3n ph\u1ea9m m\xe0 c\xf2n ho\xe0n th\xe0nh tr\u01b0\u1edbc th\u1eddi h\u1ea1n. H\u1ecfi th\u1ef1c t\u1ebf x\xed nghi\u1ec7p \u0111\xe3 r\xfat ng\u1eafn \u0111\u01b0\u1ee3c bao nhi\xeau ng\xe0y ?</p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:"<p>Theo d\u1ef1 \u0111\u1ecbnh, m\u1ed7i ng\xe0y x\xed nghi\u1ec7p s\u1ea3n xu\u1ea5t \u0111\u01b0\u1ee3c:</br>\nTh\u1ef1c t\u1ebf, m\u1ed7i ng\xe0y x\xed nghi\u1ec7p s\u1ea3n xu\u1ea5t \u0111\u01b0\u1ee3c:</br>\n      50 + 15 = 65 (s\u1ea3n ph\u1ea9m)</br>\nT\u1ed5ng s\u1ed1 s\u1ea3n ph\u1ea9m th\u1ef1c t\u1ebf x\xed nghi\u1ec7m s\u1ea3n xu\u1ea5t \u0111\u01b0\u1ee3c:</br>\n      1500 + 255 = 1755 (s\u1ea3n ph\u1ea9m)</br>\nTh\u1eddi gian th\u1ef1c t\u1ebf x\xed nghi\u1ec7m s\u1ea3n xu\u1ea5t l\xe0:</br>\n      1755 : 65 = 27 (ng\xe0y)</br>\nV\u1eady s\u1ed1 ng\xe0y \u0111\u01b0\u1ee3c r\xfat ng\u1eafn so v\u1edbi d\u1ef1 \u0111\u1ecbnh l\xe0:</br>\n      30 \u2013 27 = 3 (ng\xe0y)\n              </p>"},{id:41,extra:"",question:"<p>M\u1ed9t h\u1ee3p kim \u0111\u1ed3ng v\xe0 thi\u1ebfc c\xf3 kh\u1ed1i l\u01b0\u1ee3ng 12kg, ch\u1ee9a 45% \u0111\u1ed3ng. H\u1ecfi ph\u1ea3i th\xeam v\xe0o \u0111\xf3 bao nhi\xeau thi\u1ebfc nguy\xean ch\u1ea5t \u0111\u1ec3 \u0111\u01b0\u1ee3c h\u1ee3p kim m\u1edbi c\xf3 ch\u1ee9a 40% \u0111\u1ed3ng ?</p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:"<p>Kh\u1ed1i l\u01b0\u1ee3ng \u0111\u1ed3ng ch\u1ee9a trong h\u1ee3p khim ban \u0111\u1ea7u l\xe0: 12*0.45=5.4 kg</br>\n              Kh\u1ed1i l\u01b0\u1ee3ng thi\u1ebft ban \u0111\u1ea7u l\xe0: 12-5.4=6.6 kg</br>\n              G\u1ecdi x l\xe0 kh\xf4i l\u01b0\u1ee3ng thi\u1ebfc c\u1ea7n th\xeam v\xe0o</br>\n              Kh\u1ed1i l\u01b0\u1ee3ng h\u1ee3p kim m\u1edbi l\xe0: 12 + x</br>\n              Theo \u0111\u1ec1 b\xe0i, l\u01b0\u1ee3ng \u0111\u1ed3ng trong h\u1ee3p kim m\u1edbi chi\u1ebfm 40%, n\xean ta c\xf3 ph\u01b0\u01a1ng tr\xecnh: 5.4=(12+x).0.4\n              Gi\u1ea3i ph\u01b0\u01a1ng tr\xecnh ta \u0111\u01b0\u1ee3c x=1.5 kg</p>"},{id:41,extra:"",question:"<p>Bi\u1ebft r\u1eb1ng 200g m\u1ed9t dung d\u1ecbch ch\u1ee9a 50g mu\u1ed1i. H\u1ecfi ph\u1ea3i pha th\xeam bao nhi\xeau gam n\u01b0\u1edbc v\xe0o dung d\u1ecbch \u0111\xf3 \u0111\u1ec3 \u0111\u01b0\u1ee3c m\u1ed9t dung d\u1ecbch ch\u1ee9a 20% mu\u1ed1i ? </p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:"<p>\n              G\u1ecdi x (gam) l\xe0 kh\u1ed1i l\u01b0\u1ee3ng n\u01b0\u1edbc c\u1ea7n pha th\xeam (x>0)). Khi \u0111\xf3, kh\u1ed1i l\u01b0\u1ee3ng dung d\u1ecbch m\u1edbi s\u1ebd l\xe0: 200 +x</br>\n              N\u1ed3ng \u0111\u1ed9 dung d\u1ecbch sau khi pha lo\xe3ng l\xe0 20%=50/(200 +x)*100</br>\n              Gi\u1ea3i ph\u01b0\u01a1ng tr\xecnh ta \u0111\u01b0\u1ee3c x=50g</p>"},{id:41,extra:"",question:"<p>Hai v\xf2i n\u01b0\u1edbc c\xf9ng ch\u1ea3y m\u1ed9t b\u1ec3 c\u1ea1n th\xec ph\u1ea3i m\u1ea5t 12h m\u1edbi \u0111\u1ea7y b\u1ec3. Ng\u01b0\u1eddi ta m\u1edf hai v\xf2i c\xf9ng m\u1ed9t l\xfac, nh\u01b0ng sau \u0111\xf3 4h, ng\u01b0\u1eddi ta kh\xf3a v\xf2i I l\u1ea1i, v\xf2i II ti\u1ebfp t\u1ee5c ch\u1ea3y trong 14h n\u1eefa th\xec \u0111\u1ea7y b\u1ec3. H\u1ecfi n\u1ebfu ch\u1ea3y m\u1ed9t m\xecnh th\xec m\u1ed7i v\xf2i ph\u1ea3i ch\u1ea3y bao l\xe2u m\u1edbi \u0111\u1ea7y b\u1ec3 ?</p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:"<p>\n              G\u1ecdi th\u1eddi gian v\xf2i th\u1ee9 nh\u1ea5t v\xe0 v\xf2i th\u1ee9 2 ch\u1ea3y m\u1ed9t m\xecnh \u0111\u1ea7y b\u1ec3 l\u1ea7n l\u01b0\u1ee3t l\xe0 x (h) v\xe0 y (h) (x>0, y>0)</br>\n                V\u1eady trong 1h, v\xf2i th\u1ee9 nh\u1ea5t ch\u1ea3y \u0111\u01b0\u1ee3c 1/x b\u1ec3, v\xf2i th\u1ee9 2 ch\u1ea3y \u0111\u01b0\u1ee3c 1/y b\u1ec3.</br>\n                Khi hai v\xf2i c\xf9ng ch\u1ea3y trong 4h th\xec \u0111\u01b0\u1ee3c: 4(1/x + 1/y) b\u1ec3.</br>\n                Sau \u0111\xf3, kh\xf3a v\xf2i th\u1ee9 nh\u1ea5t, v\xf2i th\u1ee9 hai ti\u1ebfp t\u1ee5c ch\u1ea3y trong 14h th\xec \u0111\u01b0\u1ee3c: 14/y b\u1ec3.</br>\n                Theo \u0111\u1ec1 b\xe0i, ta c\xf3 ph\u01b0\u01a1ng tr\xecnh:</br>\n                4(1/x + 1/y) + 14/y = 1</br>\n                <=> 4/x + 4/y + 14/y = 1</br>\n                <=> 4/x + 18/y = 1 (1)</br>\n                Khi hai v\xf2i c\xf9ng ch\u1ea3y th\xec trong 1h ch\u1ea3y \u0111\u01b0\u1ee3c 1/12 b\u1ec3, n\xean ta c\xf3 ph\u01b0\u01a1ng tr\xecnh:</br>\n                1/x + 1/y = 1/12 (2)</br>\n                T\u1eeb (1) v\xe0 (2) ta gi\u1ea3i h\u1ec7 ph\u01b0\u01a1ng tr\xecnh \u0111\u01b0\u1ee3c:</br>\n                x = 15 (h)</br>\n                y = 20 (h)</br>\n              </p>"},{id:41,extra:"",question:"<p>M\u1ed9t c\u1eeda h\xe0ng c\xf3 hai kho ch\u1ee9a h\xe0ng. Kho I ch\u1ee9a 60 t\u1ea5n, kho II ch\u1ee9a 80 t\u1ea5n. Sau khi b\xe1n \u1edf kho II s\u1ed1 h\xe0ng g\u1ea5p 3 l\u1ea7n s\u1ed1 h\xe0ng b\xe1n \u0111\u01b0\u1ee3c \u1edf kho I thi s\u1ed1 h\xe0ng c\xf2n l\u1ea1i \u1edf kho I g\u1ea5p \u0111\xf4i s\u1ed1 h\xe0ng c\xf2n l\u1ea1i \u1edf kho II. T\xednh s\u1ed1 h\xe0ng \u0111\xe3 b\xe1n \u1edf m\u1ed7i kho</p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:"<p>\n              G\u1ecdi x (t\u1ea5n) l\xe0 s\u1ed1 h\xe0ng b\xe1n \u0111\u01b0\u1ee3c \u1edf kho I (x>0)</br>\n                V\u1eady s\u1ed1 h\xe0ng b\xe1n \u0111\u01b0\u1ee3c \u1edf kho II l\xe0 3x (t\u1ea5n)</br>\n                S\u1ed1 h\xe0ng c\xf2n l\u1ea1i \u1edf kho I l\xe0: 60 - x (t\u1ea5n)</br>\n                S\u1ed1 h\xe0ng c\xf2n l\u1ea1i \u1edf kho II l\xe0: 80 - 3x (t\u1ea5n)</br>\n                Theo \u0111\u1ec1 b\xe0i, ta c\xf3 ph\u01b0\u01a1ng tr\xecnh:</br>\n                60 - x = 2(80 - 3x)</br>\n                <=> 60 - x = 160 - 6x</br>\n                <=> 5x = 100</br>\n                <=> x = 20 </br>\n                V\u1eady s\u1ed1 h\xe0ng b\xe1n \u0111\u01b0\u1ee3c \u1edf kho I l\xe0 20 t\u1ea5n</br>\n                S\u1ed1 h\xe0ng b\xe1n \u0111\u01b0\u1ee3c \u1edf kho II l\xe0: 3.20 = 60 t\u1ea5n</br>\n              </p>\n              "},{id:41,extra:"",question:"<p>T\xecm s\u1ed1 t\u1ef1 nhi\xean c\xf3 hai ch\u1eef s\u1ed1.Bi\u1ebft r\u1eb1ng n\u1ebfu th\xeam ch\u1eef s\u1ed1 5 v\xe0o b\xean tr\xe1i s\u1ed1 \u0111\xf3 th\xec \u0111\u01b0\u1ee3c m\u1ed9t s\u1ed1 l\u1edbn h\u01a1n s\u1ed1 vi\u1ebft th\xeam ch\u1eef s\u1ed1 5 v\xe0o b\xean ph\u1ea3i s\u1ed1 \u0111\xf3</p>\n        ",options:[],answer:"",rewrite:"",lastwrite:"",explanation:'<p>\n              G\u1ecdi x l\xe0 s\u1ed1 t\u1ef1 nhi\xean c\xf3 2 ch\u1eef s\u1ed1 (10=<x<=99)</>\n              Khi vi\u1ebft th\xeam ch\u1eef s\u1ed1 5 v\xe0o b\xean tr\xe1i s\u1ed1 \u0111\xf3, ta \u0111\u01b0\u1ee3c s\u1ed1 m\u1edbi l\xe0: <span class="line_top">5ab</span> =500 +x</br>\n              Khi vi\u1ebft th\xeam ch\u1eef s\u1ed1 5 v\xe0o b\xean ph\u1ea3i s\u1ed1 \u0111\xf3, ta \u0111\u01b0\u1ee3c s\u1ed1 m\u1edbi l\xe0: <span class="line_top">ab5</span> =10*x+5</br>\n              Theo \u0111\u1ec1 b\xe0i ta c\xf3: 500 +x>10*x +5</br>\n                <=> 495 > 9*x</br>\n                <=> x < 55 (1)</br>\n                V\xec x l\xe0 s\u1ed1 c\xf3 hai ch\u1eef s\u1ed1 n\xean x>=10 (2)</br>\n                T\u1eeb (1) v\xe0 (2) ta \u0111\u01b0\u1ee3c: 10 =< x < 55</br>\n              </p>'}]}]}}]);